slow_pseudocode:
# maxnreg=32 applied — causes register spilling
@triton.autotune(configs=[
    triton.Config({...}, num_warps=4, num_stages=1, maxnreg=32),
    ...
])
def kernel(...):
    # registers spill to local memory
    tmp0 = tl.load(ptr + offset, eviction_policy='evict_first')  # streaming
    # heavy local load/store traffic due to spills

fast_pseudocode:
# No maxnreg cap — 64 registers/thread, 50% occupancy but no spills
@triton.autotune(configs=[
    triton.Config({...}, num_warps=4, num_stages=1),  # no maxnreg
    ...
])
def kernel(...):
    tmp0 = tl.load(ptr + offset, eviction_policy='evict_last')
    # no local memory spill traffic
